@@ -0,0 +1,63 @@
+import { lstatSync, realpathSync } from "node:fs";
+import { createEventBus } from "./event-bus.ts";
+import { createExtensionRuntime, loadExtensions } from "./extensions/loader.ts";
+import type { LoadExtensionsResult } from "./extensions/types.ts";
+import type { ResourceExtensionPaths, ResourceLoader, ResourceLoaderReloadOptions } from "./resource-loader.ts";
+import type { ManagedStartupPolicy } from "./startup-policy.ts";
+
+/** Explicit resources only; there is deliberately no package manager or discovery fallback. */
+export class ManagedResourceLoader implements ResourceLoader {
+	private readonly policy: ManagedStartupPolicy;
+	private readonly eventBus = createEventBus();
+	private extensions: LoadExtensionsResult = { extensions: [], errors: [], runtime: createExtensionRuntime() };
+
+	constructor(policy: ManagedStartupPolicy) {
+		this.policy = Object.freeze({ ...policy, extensionPaths: Object.freeze([...policy.extensionPaths]) });
+	}
+
+	getExtensions(): LoadExtensionsResult {
+		return this.extensions;
+	}
+	getSkills() {
+		return { skills: [], diagnostics: [] };
+	}
+	getPrompts() {
+		return { prompts: [], diagnostics: [] };
+	}
+	getThemes() {
+		return { themes: [], diagnostics: [] };
+	}
+	getAgentsFiles() {
+		return { agentsFiles: [] };
+	}
+	getSystemPrompt(): string {
+		return this.policy.systemPrompt;
+	}
+	getSystemPromptSource(): undefined {
+		return undefined;
+	}
+	getAppendSystemPrompt(): string[] {
+		return [];
+	}
+	getAppendSystemPromptSources(): Array<{ path: string }> {
+		return [];
+	}
+
+	extendResources(paths: ResourceExtensionPaths): void {
+		if (paths.skillPaths?.length || paths.promptPaths?.length || paths.themePaths?.length) {
+			throw new Error("managed-v1 does not allow discovered resource expansion");
+		}
+	}
+
+	async reload(options?: ResourceLoaderReloadOptions): Promise<void> {
+		if (options?.resolveProjectTrust) throw new Error("managed-v1 does not resolve project trust");
+		const paths = this.policy.extensionPaths.map((path) => {
+			if (!lstatSync(path).isFile()) throw new Error("managed-v1 extension must be a regular file");
+			return realpathSync(path);
+		});
+		if (new Set(paths).size !== paths.length) throw new Error("Duplicate managed extension identity");
+		const extensions = await loadExtensions(paths, this.policy.cwd, this.eventBus);
+		if (extensions.errors.length > 0) throw new Error("managed-v1 could not load an explicit extension");
+		this.extensions = extensions;
+	}
+}
diff --git a/packages/coding-agent/src/core/startup-policy.ts b/packages/coding-agent/src/core/startup-policy.ts
new file mode 100644
index 000000000..71799ccab
--- /dev/null
+++ b/packages/coding-agent/src/core/startup-policy.ts
@@ -0,0 +1,72 @@
+import { isAbsolute, normalize } from "node:path";
+import type { Args } from "../cli/args.ts";
+
+/** Host-selected inputs for the closed, keyless managed startup contract. */
+export interface ManagedStartupPolicy {
+	readonly kind: "managed-v1";
+	readonly cwd: string;
+	readonly agentDir: string;
+	readonly sessionDir: string;
+	readonly systemPrompt: string;
+	readonly extensionPaths: readonly string[];
+}
+
+/** Pure validation: must run before command handlers or configuration I/O. */
+export function resolveStartupPolicy(
+	args: readonly string[],
+	parsed: Args,
+	env: NodeJS.ProcessEnv,
+	cwd: string,
+): ManagedStartupPolicy | undefined {
+	if (parsed.startupPolicy === undefined) return undefined;
+	if (parsed.startupPolicy !== "managed-v1") throw new Error("Unsupported startup policy");
+	if (parsed.diagnostics.length > 0) throw new Error(parsed.diagnostics.map((item) => item.message).join("; "));
+	const values = new Set(["--startup-policy", "--mode", "--session-dir", "--system-prompt", "--extension"]);
+	const switches = new Set([
+		"--no-extensions",
+		"--no-skills",
+		"--no-prompt-templates",
+		"--no-themes",
+		"--no-context-files",
+		"--no-approve",
+		"--offline",
+		"--no-tools",
+		"--no-builtin-tools",
+		"--help",
+		"--version",
+	]);
+	const seen = new Set<string>();
+	for (let index = 0; index < args.length; index++) {
+		const arg = args[index];
+		if (!values.has(arg) && !switches.has(arg)) throw new Error(`managed-v1 does not support ${arg}`);
+		if (seen.has(arg) && arg !== "--extension") throw new Error(`Duplicate managed option: ${arg}`);
+		seen.add(arg);
+		if (values.has(arg)) {
+			const value = args[++index];
+			if (value === undefined) throw new Error(`Missing value for ${arg}`);
+			if (arg === "--mode" && value !== "rpc") throw new Error("managed-v1 supports interactive or RPC mode");
+		}
+	}
+	const agentDir = env.PI_CODING_AGENT_DIR;
+	const sessionDir = parsed.sessionDir;
+	if (!agentDir || !isAbsolute(agentDir) || !sessionDir || !isAbsolute(sessionDir) || !isAbsolute(cwd)) {
+		throw new Error("managed-v1 requires absolute cwd, agent and session directories");
+	}
+	if (env.PI_CODING_AGENT_SESSION_DIR && normalize(env.PI_CODING_AGENT_SESSION_DIR) !== normalize(sessionDir)) {
+		throw new Error("managed-v1 session directory inputs disagree");
+	}
+	if (!parsed.systemPrompt) throw new Error("managed-v1 requires an explicit literal system prompt");
+	const extensionPaths = (parsed.extensions ?? []).map((path) => {
+		if (!isAbsolute(path)) throw new Error("managed-v1 requires absolute extension file paths");
+		return normalize(path);
+	});
+	if (new Set(extensionPaths).size !== extensionPaths.length) throw new Error("Duplicate managed extension path");
+	return Object.freeze({
+		kind: "managed-v1",
+		cwd: normalize(cwd),
+		agentDir: normalize(agentDir),
+		sessionDir: normalize(sessionDir),
+		systemPrompt: parsed.systemPrompt,
+		extensionPaths: Object.freeze(extensionPaths),
+	});
+}
