diff --git a/packages/coding-agent/test/managed-startup-policy.test.ts b/packages/coding-agent/test/managed-startup-policy.test.ts
new file mode 100644
index 000000000..fc14efa21
--- /dev/null
+++ b/packages/coding-agent/test/managed-startup-policy.test.ts
@@ -0,0 +1,195 @@
+import {
+	existsSync,
+	mkdirSync,
+	mkdtempSync,
+	readFileSync,
+	realpathSync,
+	rmSync,
+	symlinkSync,
+	writeFileSync,
+} from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
+import { parseArgs } from "../src/cli/args.ts";
+import { type CreateAgentSessionRuntimeFactory, createAgentSessionRuntime } from "../src/core/agent-session-runtime.ts";
+import { createAgentSessionFromServices, createAgentSessionServices } from "../src/core/agent-session-services.ts";
+import { AuthStorage } from "../src/core/auth-storage.ts";
+import { ManagedResourceLoader } from "../src/core/managed-resource-loader.ts";
+import { ModelConfig } from "../src/core/model-config.ts";
+import { DefaultPackageManager } from "../src/core/package-manager.ts";
+import { DefaultResourceLoader } from "../src/core/resource-loader.ts";
+import { SessionManager } from "../src/core/session-manager.ts";
+import { SettingsManager } from "../src/core/settings-manager.ts";
+import { type ManagedStartupPolicy, resolveStartupPolicy } from "../src/core/startup-policy.ts";
+
+// Regression: https://github.com/psmfd/pi/issues/80
+// Actual CLI startup and migration ordering are also exercised by FingerTrap's
+// digest-selected executable qualifier; these tests cover the policy boundaries.
+describe("managed-v1 startup policy", () => {
+	let root: string;
+	let cwd: string;
+	let agentDir: string;
+	let sessionDir: string;
+	let argv: string[];
+	beforeEach(() => {
+		root = realpathSync(mkdtempSync(join(tmpdir(), "pi-managed-test-")));
+		cwd = join(root, "project");
+		agentDir = join(root, "agent");
+		sessionDir = join(root, "sessions");
+		for (const path of [cwd, agentDir, sessionDir]) mkdirSync(path);
+		vi.stubEnv("PI_CODING_AGENT_DIR", agentDir);
+		argv = ["--startup-policy", "managed-v1", "--session-dir", sessionDir, "--system-prompt", "literal"];
+	});
+	afterEach(() => {
+		vi.restoreAllMocks();
+		vi.unstubAllEnvs();
+		rmSync(root, { recursive: true, force: true });
+	});
+	function policy(args = argv): ManagedStartupPolicy {
+		return resolveStartupPolicy(args, parseArgs(args), { PI_CODING_AGENT_DIR: agentDir }, cwd)!;
+	}
+	it("leaves ordinary CLI input outside the opt-in policy", () => {
+		const args = ["--resume", "previous", "hello"];
+		expect(resolveStartupPolicy(args, parseArgs(args), {}, cwd)).toBeUndefined();
+	});
+	it("freezes explicit inputs and preserves a filename-shaped prompt literally", () => {
+		const prompt = join(root, "prompt.md");
+		writeFileSync(prompt, "ambient content");
+		argv[argv.length - 1] = prompt;
+		const resolved = policy();
+		expect(resolved.systemPrompt).toBe(prompt);
+		expect(Object.isFrozen(resolved)).toBe(true);
+		expect(Object.isFrozen(resolved.extensionPaths)).toBe(true);
+	});
+	it.each([
+		["install", "npm:package"],
+		["auth", "login"],
+		["config"],
+		["--resume", "file"],
+		["--continue"],
+		["--session", "file"],
+		["--system-prompt-file", "file"],
+		["--project-trust"],
+		["--provider", "openai"],
+		["--api-key", "synthetic"],
+		["--extension", "npm:package"],
+		["--extension", "relative.mjs"],
+		["--mode", "json"],
+		["--startup-policy", "managed-v1"],
+		["--unknown"],
+		["@prompt.md"],
+		["hello"],
+	])("rejects unsupported input before resource construction: %j", (...extra) => {
+		expect(() => policy([...argv, ...extra])).toThrow();
+	});
+	it("rejects unknown versions, missing roots, conflicting roots and duplicate extension identities", () => {
+		expect(() => policy(argv.map((value) => (value === "managed-v1" ? "managed-v2" : value)))).toThrow();
+		expect(() => resolveStartupPolicy(argv, parseArgs(argv), {}, cwd)).toThrow();
+		expect(() =>
+			resolveStartupPolicy(
+				argv,
+				parseArgs(argv),
+				{
+					PI_CODING_AGENT_DIR: agentDir,
+					PI_CODING_AGENT_SESSION_DIR: join(root, "other"),
+				},
+				cwd,
+			),
+		).toThrow();
+		const path = join(root, "explicit.mjs");
+		expect(() => policy([...argv, "--extension", path, "--extension", path])).toThrow();
+	});
+	it("loads only explicit files exactly once per reload and never reads prompt/context files", async () => {
+		const log = join(root, "loads.txt");
+		const explicit = join(root, "explicit.mjs");
+		writeFileSync(
+			explicit,
+			`import { appendFileSync } from "node:fs"; export default () => appendFileSync(new URL("./loads.txt", import.meta.url), "load\\n");`,
+		);
+		mkdirSync(join(cwd, ".pi", "extensions"), { recursive: true });
+		writeFileSync(join(cwd, ".pi", "extensions", "bad.mjs"), "throw new Error('ambient loaded');");
+		writeFileSync(join(cwd, "AGENTS.md"), "ambient content");
+		writeFileSync(join(agentDir, "SYSTEM.md"), "ambient content");
+		const loader = new ManagedResourceLoader(policy([...argv, "--extension", explicit]));
+		await loader.reload();
+		await loader.reload();
+		expect(readFileSync(log, "utf8")).toBe("load\nload\n");
+		expect(loader.getExtensions().extensions).toHaveLength(1);
+		expect(loader.getSystemPrompt()).toBe("literal");
+		expect(loader.getAgentsFiles().agentsFiles).toEqual([]);
+		expect(loader.getAppendSystemPrompt()).toEqual([]);
+		expect(loader.getSkills().skills).toEqual([]);
+		expect(loader.getPrompts().prompts).toEqual([]);
+		expect(loader.getThemes().themes).toEqual([]);
+		expect(() =>
+			loader.extendResources({
+				themePaths: [{ path: explicit, metadata: { source: "explicit", scope: "user", origin: "top-level" } }],
+			}),
+		).toThrow("resource expansion");
+	});
+	it("rejects directories, symlinks and failed explicit extension loads", async () => {
+		const explicit = join(root, "broken.mjs");
+		writeFileSync(explicit, "throw new Error('broken explicit');");
+		const linked = join(root, "linked.mjs");
+		symlinkSync(explicit, linked);
+		for (const path of [cwd, linked, explicit]) {
+			await expect(new ManagedResourceLoader(policy([...argv, "--extension", path])).reload()).rejects.toThrow();
+		}
+	});
+	it("keeps settings, auth and model configuration in memory across reload and new sessions", async () => {
+		for (const name of ["settings.json", "auth.json", "models.json", "models-store.json"]) {
+			writeFileSync(join(agentDir, name), "{invalid ambient config");
+		}
+		// These traps fail even for a harmless read or an offline package lookup.
+		const implicitRead = () => {
+			throw new Error("implicit configuration path reached");
+		};
+		vi.spyOn(SettingsManager, "create").mockImplementation(implicitRead);
+		vi.spyOn(AuthStorage, "create").mockImplementation(implicitRead);
+		vi.spyOn(DefaultResourceLoader.prototype, "reload").mockImplementation(implicitRead);
+		vi.spyOn(DefaultPackageManager.prototype, "resolve").mockImplementation(implicitRead);
+		const modelConfigLoad = vi.spyOn(ModelConfig, "load");
+		const selectedPolicy = policy();
+		const factory: CreateAgentSessionRuntimeFactory = async ({ cwd: nextCwd, sessionManager, sessionStartEvent }) => {
+			const services = await createAgentSessionServices({ cwd: nextCwd, agentDir, startupPolicy: selectedPolicy });
+			expect(services.settingsManager.getCacheWarmingMode()).toBe("off");
+			return {
+				...(await createAgentSessionFromServices({ services, sessionManager, sessionStartEvent, noTools: "all" })),
+				services,
+				diagnostics: services.diagnostics,
+			};
+		};
+		const runtime = await createAgentSessionRuntime(factory, {
+			cwd,
+			agentDir,
+			sessionManager: SessionManager.create(cwd, sessionDir),
+		});
+		try {
+			await runtime.session.bindExtensions({});
+			await runtime.session.reload();
+			expect(runtime.services.settingsManager.getCacheWarmingMode()).toBe("off");
+			await runtime.newSession();
+			expect(runtime.cwd).toBe(cwd);
+			expect(modelConfigLoad).toHaveBeenCalled();
+			expect(modelConfigLoad.mock.calls.every(([path]) => path === undefined)).toBe(true);
+			expect(runtime.session.systemPrompt).toContain("literal");
+			expect(runtime.session.sessionManager.getSessionDir()).toBe(sessionDir);
+			const session = runtime.session;
+			await expect(runtime.switchSession(join(root, "missing.jsonl"))).rejects.toThrow("managed-v1");
+			await expect(runtime.importFromJsonl(join(root, "missing.jsonl"))).rejects.toThrow("managed-v1");
+			await expect(runtime.fork("entry")).rejects.toThrow("managed-v1");
+			await expect(runtime.newSession({ parentSession: join(root, "parent.jsonl") })).rejects.toThrow("managed-v1");
+			expect(runtime.session).toBe(session);
+			await expect(
+				createAgentSessionServices({ cwd: root, agentDir, startupPolicy: selectedPolicy }),
+			).rejects.toThrow("roots");
+			for (const name of ["settings.json", "auth.json", "models.json", "models-store.json"]) {
+				expect(readFileSync(join(agentDir, name), "utf8")).toBe("{invalid ambient config");
+			}
+			expect(existsSync(join(agentDir, "trust.json"))).toBe(false);
+		} finally {
+			await runtime.dispose();
+		}
+	});
+});
diff --git a/packages/coding-agent/test/rpc-hello.test.ts b/packages/coding-agent/test/rpc-hello.test.ts
new file mode 100644
index 000000000..4fb78691e
--- /dev/null
+++ b/packages/coding-agent/test/rpc-hello.test.ts
@@ -0,0 +1,104 @@
+import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { afterEach, describe, expect, test } from "vitest";
+import { VERSION } from "../src/config.ts";
+import { RpcClient } from "../src/modes/rpc/rpc-client.ts";
+import { helloFrame, RPC_PROTOCOL_VERSION } from "../src/modes/rpc/rpc-mode.ts";
+
+// PSMFD-Patch: psmfd-patch-010 (psmfd/pi#56) — the RPC hello line and the
+// reference client's hello-based ready gate. Keyless: the child side is a
+// scripted stdio double, same seam as rpc-client-process-exit.test.ts.
+
+const tempDirs: string[] = [];
+
+function writeChildScript(contents: string): string {
+	const dir = mkdtempSync(join(tmpdir(), "pi-rpc-hello-"));
+	tempDirs.push(dir);
+	const path = join(dir, "child.mjs");
+	writeFileSync(path, contents);
+	return path;
+}
+
+afterEach(() => {
+	for (const dir of tempDirs.splice(0)) {
+		rmSync(dir, { recursive: true, force: true });
+	}
+});
+
+describe("hello frame", () => {
+	test("carries version, protocol, and capabilities", () => {
+		const frame = helloFrame();
+		expect(frame.type).toBe("hello");
+		expect(frame.piVersion).toBe(VERSION);
+		expect(frame.protocol).toBe(RPC_PROTOCOL_VERSION);
+		// Literal list on purpose: a new upstream command must be advertised here
+		// deliberately, never inherited silently from the constant (v0.85.1 sync
+		// review: clear_queue was wired but unadvertised).
+		expect(frame.capabilities).toEqual([
+			"extension_ui",
+			"queue_modes",
+			"fork",
+			"get_commands",
+			"list_sessions",
+			"clear_queue",
+		]);
+	});
+});
+
+describe("RpcClient hello gating", () => {
+	test("consumes the hello line as the ready gate", async () => {
+		const client = new RpcClient({
+			cliPath: writeChildScript(`
+process.stdout.write(JSON.stringify({ type: "hello", piVersion: "9.9.9-test", protocol: 1, capabilities: ["extension_ui"] }) + "\\n");
+process.stdin.resume();
+`),
+			// Generous: a loaded machine can take >250ms just to start node.
+			helloGraceMs: 10_000,
+		});
+		const events: unknown[] = [];
+		client.onEvent((event) => events.push(event));
+		await client.start();
+		try {
+			expect(client.hello).toEqual({
+				type: "hello",
+				piVersion: "9.9.9-test",
+				protocol: 1,
+				capabilities: ["extension_ui"],
+			});
+			// The handshake frame is not a session event.
+			expect(events).toEqual([]);
+		} finally {
+			await client.stop();
+		}
+	});
+
+	test("falls back to the legacy grace for a child that never says hello", async () => {
+		const client = new RpcClient({
+			cliPath: writeChildScript(`
+process.stdin.resume();
+`),
+		});
+		await client.start();
+		try {
+			expect(client.hello).toBeNull();
+		} finally {
+			await client.stop();
+		}
+	});
+
+	test("refuses a protocol newer than supported, naming both versions", async () => {
+		const client = new RpcClient({
+			cliPath: writeChildScript(`
+process.stdout.write(JSON.stringify({ type: "hello", piVersion: "9.9.9-test", protocol: 99, capabilities: [] }) + "\\n");
+process.stdin.resume();
+`),
+			helloGraceMs: 10_000,
+		});
+		try {
+			await expect(client.start()).rejects.toThrow(/protocol 99[\s\S]*supports 1/);
+		} finally {
+			await client.stop();
+		}
+	});
+});
diff --git a/packages/coding-agent/test/rpc-list-sessions.test.ts b/packages/coding-agent/test/rpc-list-sessions.test.ts
new file mode 100644
index 000000000..5b35a93da
--- /dev/null
+++ b/packages/coding-agent/test/rpc-list-sessions.test.ts
@@ -0,0 +1,151 @@
+import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { afterEach, beforeAll, describe, expect, test } from "vitest";
+import type { SessionHeader, SessionInfo } from "../src/core/session-manager.ts";
+import { SessionManager } from "../src/core/session-manager.ts";
+import { initTheme } from "../src/modes/interactive/theme/theme.ts";
+import { RpcClient } from "../src/modes/rpc/rpc-client.ts";
+import { listSessionsForRpc, RPC_CAPABILITIES, toRpcSessionInfo } from "../src/modes/rpc/rpc-mode.ts";
+
+// PSMFD-Patch: psmfd-patch-011 (psmfd/pi#54) — the list_sessions RPC command:
+// SessionManager.list()/.listAll() exposed as header fields only, with
+// allMessagesText deliberately kept off the wire (it scales with transcript
+// size; pickers need firstMessage at most).
+
+const tempDirs: string[] = [];
+
+function makeTempDir(prefix: string): string {
+	const dir = mkdtempSync(join(tmpdir(), prefix));
+	tempDirs.push(dir);
+	return dir;
+}
+
+function createSessionFile(path: string, id: string, cwd: string): void {
+	const header: SessionHeader = {
+		type: "session",
+		id,
+		version: 3,
+		timestamp: new Date(0).toISOString(),
+		cwd,
+	};
+	writeFileSync(path, `${JSON.stringify(header)}\n`, "utf8");
+	const mgr = SessionManager.open(path);
+	mgr.appendMessage({
+		role: "assistant",
+		content: [{ type: "text", text: "hello from the fixture" }],
+		api: "openai-completions",
+		provider: "openai",
+		model: "test",
+		usage: {
+			input: 1,
+			output: 1,
+			cacheRead: 0,
+			cacheWrite: 0,
+			totalTokens: 2,
+			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
+		},
+		stopReason: "stop",
+		timestamp: Date.now(),
+	});
+	// firstMessage derives from the first USER message only.
+	mgr.appendMessage({
+		role: "user",
+		content: [{ type: "text", text: "hello from the fixture" }],
+		timestamp: Date.now(),
+	});
+}
+
+afterEach(() => {
+	for (const dir of tempDirs.splice(0)) {
+		rmSync(dir, { recursive: true, force: true });
+	}
+});
+
+describe("toRpcSessionInfo", () => {
+	test("projects header fields and keeps allMessagesText off the wire", () => {
+		const info: SessionInfo = {
+			path: "/tmp/s.jsonl",
+			id: "sess-1",
+			cwd: "/tmp/project",
+			name: "named",
+			parentSessionPath: "/tmp/parent.jsonl",
+			created: new Date("2026-08-20T10:00:00.000Z"),
+			modified: new Date("2026-08-20T11:00:00.000Z"),
+			messageCount: 3,
+			firstMessage: "first",
+			allMessagesText: "first second third — potentially megabytes",
+		};
+		const wire = toRpcSessionInfo(info);
+		expect(wire).toEqual({
+			path: "/tmp/s.jsonl",
+			id: "sess-1",
+			cwd: "/tmp/project",
+			name: "named",
+			parentSessionPath: "/tmp/parent.jsonl",
+			created: "2026-08-20T10:00:00.000Z",
+			modified: "2026-08-20T11:00:00.000Z",
+			messageCount: 3,
+			firstMessage: "first",
+		});
+		expect("allMessagesText" in wire).toBe(false);
+	});
+});
+
+describe("listSessionsForRpc", () => {
+	beforeAll(() => initTheme("dark"));
+
+	test("lists real session files, projected", async () => {
+		const sessionDir = makeTempDir("pi-rpc-list-");
+		createSessionFile(join(sessionDir, "a.jsonl"), "sess-a", "/tmp/project");
+		const sessions = await listSessionsForRpc({ cwd: "/tmp/project", sessionDir });
+		expect(sessions).toHaveLength(1);
+		expect(sessions[0].id).toBe("sess-a");
+		expect(sessions[0].messageCount).toBe(2);
+		expect(sessions[0].firstMessage).toContain("hello from the fixture");
+		expect(typeof sessions[0].created).toBe("string");
+		expect("allMessagesText" in sessions[0]).toBe(false);
+	});
+});
+
+describe("capabilities", () => {
+	test("hello advertises list_sessions", () => {
+		expect(RPC_CAPABILITIES).toContain("list_sessions");
+	});
+});
+
+describe("RpcClient.listSessions", () => {
+	test("round-trips the command through a scripted child", async () => {
+		const dir = makeTempDir("pi-rpc-list-child-");
+		const childPath = join(dir, "child.mjs");
+		writeFileSync(
+			childPath,
+			`
+import * as readline from "node:readline";
+const rl = readline.createInterface({ input: process.stdin });
+rl.on("line", (line) => {
+	const cmd = JSON.parse(line);
+	if (cmd.type === "list_sessions") {
+		process.stdout.write(JSON.stringify({
+			id: cmd.id,
+			type: "response",
+			command: "list_sessions",
+			success: true,
+			data: { sessions: [{ path: "/tmp/s.jsonl", id: "sess-child", cwd: cmd.cwd ?? "", created: "2026-08-20T10:00:00.000Z", modified: "2026-08-20T10:00:00.000Z", messageCount: 1, firstMessage: "hi" }] },
+		}) + "\\n");
+	}
+});
+`,
+		);
+		const client = new RpcClient({ cliPath: childPath });
+		await client.start();
+		try {
+			const result = await client.listSessions({ cwd: "/tmp/project" });
+			expect(result.sessions).toHaveLength(1);
+			expect(result.sessions[0].id).toBe("sess-child");
+			expect(result.sessions[0].cwd).toBe("/tmp/project");
+		} finally {
+			await client.stop();
+		}
+	});
+});
